import React from 'react';
// Assume you have a simple Icon component that handles colors and size
const Icon = ({ name, emoji, isActive, onClick, isEasyMode }) => (
    <div 
        onClick={onClick}
        style={{
            padding: '20px',
            margin: '10px',
            border: `5px solid ${isActive ? 'blue' : isEasyMode ? 'gray' : '#ccc'}`,
            borderRadius: '10px',
            width: '40%',
            textAlign: 'center',
            backgroundColor: isActive ? 'lightblue' : 'white',
            cursor: isActive ? 'pointer' : 'default',
            opacity: isActive || !isEasyMode ? 1 : 0.5, // Mute non-active icons in Easy Mode
            fontSize: isEasyMode ? '36px' : '20px',
        }}
    >
        <span role="img" aria-label={name} style={{fontSize: isEasyMode ? '80px' : '40px'}}>{emoji}</span>
        <p style={{fontWeight: 'bold'}}>{name}</p>
    </div>
);

// /frontend-react/src/components/Dashboard.js

// ... (Icon component remains the same)

function Dashboard({ isEasyMode, goToMedical }) { // goToMedical now points to the MedicalDashboard
    return (
        <div style={{ 
            display: 'flex', 
            flexWrap: 'wrap', 
            justifyContent: 'center',
            paddingTop: '20px' // Add padding for app look
        }}>
            <Icon
                name="Medical"
                emoji="🏥"
                isActive={true} 
                onClick={goToMedical} // This triggers navigation to the 3-icon page
                isEasyMode={isEasyMode}
            />
            {/* ... (other three Icons remain Muted) ... */}
        </div>
    );
}


export default Dashboard;
